-- Joe&dave Operations Intelligence — D1 migration 0002
-- Add supplier, expense, purchase-order and accounting support.
CREATE TABLE IF NOT EXISTS jd_invoice_counters (business_id TEXT PRIMARY KEY REFERENCES jd_businesses(id), next_number INTEGER NOT NULL DEFAULT 1 CHECK(next_number>0));
CREATE TABLE IF NOT EXISTS jd_suppliers (id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES jd_businesses(id),name TEXT NOT NULL,email TEXT,phone TEXT,address TEXT,tax_id TEXT,notes TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS jd_suppliers_business_idx ON jd_suppliers(business_id);
CREATE TABLE IF NOT EXISTS jd_expenses (id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES jd_businesses(id),supplier_id TEXT REFERENCES jd_suppliers(id),category TEXT NOT NULL,description TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor>0),currency_code TEXT NOT NULL,payment_method TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'paid' CHECK(status IN ('draft','paid','void')),expense_date TEXT NOT NULL,reference TEXT,created_by TEXT REFERENCES jd_users(id),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS jd_expenses_business_date_idx ON jd_expenses(business_id,expense_date);
CREATE TABLE IF NOT EXISTS jd_purchase_orders (id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES jd_businesses(id),supplier_id TEXT NOT NULL REFERENCES jd_suppliers(id),order_number TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','ordered','part_received','received','cancelled')),order_date TEXT NOT NULL,due_date TEXT,total_minor INTEGER NOT NULL DEFAULT 0 CHECK(total_minor>=0),notes TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(business_id,order_number));
CREATE TABLE IF NOT EXISTS jd_purchase_order_lines (id TEXT PRIMARY KEY,purchase_order_id TEXT NOT NULL REFERENCES jd_purchase_orders(id) ON DELETE CASCADE,item_id TEXT REFERENCES jd_inventory_items(id),description TEXT NOT NULL,quantity REAL NOT NULL CHECK(quantity>0),unit_cost_minor INTEGER NOT NULL CHECK(unit_cost_minor>=0),line_total_minor INTEGER NOT NULL CHECK(line_total_minor>=0),received_quantity REAL NOT NULL DEFAULT 0 CHECK(received_quantity>=0));
CREATE TABLE IF NOT EXISTS jd_journal_entries (id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES jd_businesses(id),entry_date TEXT NOT NULL,source_type TEXT NOT NULL,source_id TEXT,description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'posted' CHECK(status IN ('draft','posted','void')),created_by TEXT REFERENCES jd_users(id),created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE IF NOT EXISTS jd_journal_lines (id TEXT PRIMARY KEY,entry_id TEXT NOT NULL REFERENCES jd_journal_entries(id) ON DELETE CASCADE,account_code TEXT NOT NULL,account_name TEXT NOT NULL,debit_minor INTEGER NOT NULL DEFAULT 0 CHECK(debit_minor>=0),credit_minor INTEGER NOT NULL DEFAULT 0 CHECK(credit_minor>=0),CHECK((debit_minor=0 AND credit_minor>0) OR (credit_minor=0 AND debit_minor>0)));
CREATE INDEX IF NOT EXISTS jd_journal_business_date_idx ON jd_journal_entries(business_id,entry_date);
CREATE TABLE IF NOT EXISTS jd_auth_attempts (id TEXT PRIMARY KEY,ip_hash TEXT NOT NULL,email_hash TEXT NOT NULL,success INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX IF NOT EXISTS jd_auth_attempts_lookup_idx ON jd_auth_attempts(ip_hash,email_hash,created_at);
DROP TRIGGER IF EXISTS jd_stock_insert;
CREATE TRIGGER IF NOT EXISTS jd_stock_guard BEFORE INSERT ON jd_stock_movements WHEN (SELECT quantity FROM jd_inventory_items WHERE id=NEW.item_id AND business_id=NEW.business_id) IS NULL OR (SELECT quantity+NEW.quantity_delta FROM jd_inventory_items WHERE id=NEW.item_id AND business_id=NEW.business_id)<0 BEGIN SELECT RAISE(ABORT,'invalid stock movement or insufficient stock'); END;
CREATE TRIGGER IF NOT EXISTS jd_stock_insert AFTER INSERT ON jd_stock_movements BEGIN UPDATE jd_inventory_items SET quantity=quantity+NEW.quantity_delta WHERE id=NEW.item_id AND business_id=NEW.business_id; END;
DROP TRIGGER IF EXISTS jd_receipt_guard;
CREATE TRIGGER IF NOT EXISTS jd_receipt_guard BEFORE INSERT ON jd_receipts WHEN (SELECT business_id FROM jd_invoices WHERE id=NEW.invoice_id) IS NULL OR (SELECT business_id FROM jd_invoices WHERE id=NEW.invoice_id)<>NEW.business_id OR (SELECT status FROM jd_invoices WHERE id=NEW.invoice_id) IN ('draft','void') OR NEW.amount_minor > (SELECT total_minor-paid_minor FROM jd_invoices WHERE id=NEW.invoice_id) BEGIN SELECT RAISE(ABORT,'receipt requires an issued invoice and cannot exceed outstanding balance'); END;
CREATE TRIGGER IF NOT EXISTS jd_journal_balance_guard BEFORE UPDATE OF status ON jd_journal_entries WHEN NEW.status='posted' AND ((SELECT COALESCE(SUM(debit_minor),0) FROM jd_journal_lines WHERE entry_id=NEW.id)<>(SELECT COALESCE(SUM(credit_minor),0) FROM jd_journal_lines WHERE entry_id=NEW.id) OR (SELECT COUNT(*) FROM jd_journal_lines WHERE entry_id=NEW.id)<2) BEGIN SELECT RAISE(ABORT,'journal entry must balance and contain at least two lines'); END;

CREATE TABLE IF NOT EXISTS jd_purchase_order_counters (business_id TEXT PRIMARY KEY REFERENCES jd_businesses(id), next_number INTEGER NOT NULL DEFAULT 1 CHECK(next_number>0));

CREATE TRIGGER IF NOT EXISTS jd_purchase_received_guard BEFORE UPDATE OF received_quantity ON jd_purchase_order_lines WHEN NEW.received_quantity<OLD.received_quantity OR NEW.received_quantity>NEW.quantity BEGIN SELECT RAISE(ABORT,'received quantity must be monotonic and cannot exceed ordered quantity'); END;
